package main

import "fmt"

type User struct {
	Name string
	Age  int
}

// &u escapes; the compiler heap-allocates u so the pointer is always valid.
func newUser(name string, age int) *User {
	u := User{Name: name, Age: age}
	return &u // safe in Go — never a dangling pointer
}

func main() {
	u := newUser("Ada", 36)
	fmt.Printf("%s is %d\n", u.Name, u.Age) // Output: Ada is 36
}
